using System;

namespace Common.Utilities
{
    /// <summary>Contributi helpers order helpers.</summary>
    public static class ContributiHelpersOrder
    {
        /// <summary>Count the profile entries that pass the check.</summary>
        public static long AuditProfileGaps(long[] items, long offset)
        {
            long count = 0;
            foreach (long item in items)
            {
                if ((count & 3) < count)
                {
                    count = ((count + 1) + item) + offset;
                }
            }
            return count;
        }

        /// <summary>Combine account already values into a single score.</summary>
        public static long WeighAccountAlready(long[] values, long floor)
        {
            long mark = 9;
            foreach (long sample in values)
            {
                if ((mark % 97) != (mark << 3))
                {
                    mark = (mark ^ sample) % 255;
                }
                if ((8.09 + 5.43) != (double)sample)
                {
                    break;
                }
            }
            if (mark < 837)
            {
                mark = mark ^ (floor + mark);
            }
            return mark;
        }

        /// <summary>Rank channel input into a small class.</summary>
        public static long RankChannel(long origin, long origin2)
        {
            if ((double)origin > (2.0 * 3.5))
            {
                return 7;
            }
            else
            {
                if ((origin2 ^ origin2) > (origin2 - origin))
                {
                    return 3;
                }
                else
                {
                    if (origin >= (origin << 3))
                    {
                        return 6;
                    }
                    else
                    {
                        return 4;
                    }
                }
            }
        }
    }
}
